mapper.select:
SELECT a.alarm_id, a.alarm_time, a.province_name, a.province_code, a.city_name, a.city_code, a.county_code, a.county_name, a.device_code, a.device_name, a.original_picture_url, a.alarm_picture_url, a.vehicle_number,
when vehicle_type=#{item.dictValue} then #{item.dictLabel}
concat(a.province_name, a.city_name, a.county_name) areaName, a.vehicle_color, a.vehicle_num_color FROM vm_checkpoint_warning_order_t a WHERE a.delete_flag = 0
and a.province_code = #{provinceCode}
and a.city_code = #{cityCode}
and a.county_code = #{countyCode}
and a.vehicle_number like concat('%',#{vehicleNumber},'%')
and a.vehicle_type = #{vehicleType}
and a.device_code like CONCAT('%', #{deviceCode}, '%')
AND a.device_name like CONCAT('%', #{deviceName}, '%')
and #{alarmTimeEnd} >= a.alarm_time
and a.alarm_time >= #{alarmTimeStart}
and a.vehicle_color = #{vehicleColor}
and a.vehicle_num_color = #{vehicleNumColor}
and a.device_code in
#{item}
${dataScope}
order by a.device_code, a.alarm_time DESC
order by CONVERT(a.device_name USING GBK), a.alarm_time DESC
order by CONVERT(areaName USING GBK), a.alarm_time DESC
order by a.vehicle_type, a.alarm_time DESC
order by a.vehicle_number, a.alarm_time DESC
order by a.alarm_time, a.vehicle_number
order by a.device_code DESC, a.alarm_time DESC
order by CONVERT(a.device_name USING GBK) DESC, a.alarm_time DESC
order by CONVERT(areaName USING GBK) DESC, a.alarm_time DESC
order by a.vehicle_type DESC, a.alarm_time DESC
order by a.vehicle_number DESC, a.alarm_time DESC
order by a.alarm_time DESC, a.vehicle_number
order by a.alarm_time desc,a.alarm_id desc

SELECT  a.vehicle_number,



                    when vehicle_type=#{item.dictValue} then #{item.dictLabel}



        concat(a.province_name, a.city_name, a.county_name) areaName,
        a.device_name,
        a.device_code,
        a.alarm_time
FROM vm_checkpoint_warning_order_t a
WHERE a.delete_flag = 0

    and a.device_code in

        #{item}


${dataScope}


        AND a.alarm_id in

            #{item}




            and a.province_code = #{provinceCode}


            and a.city_code = #{cityCode}


            and a.county_code = #{countyCode}


            and a.vehicle_number like concat('%',#{vehicleNumber},'%')


            and a.device_code like CONCAT('%', #{deviceCode}, '%')


            AND a.device_name like CONCAT('%', #{deviceName}, '%')


            and date_format(#{alarmTimeEnd},'%Y-%c-%d %h:%i:%s') > a.alarm_time


            and a.alarm_time > date_format(#{alarmTimeStart},'%Y-%c-%d %h:%i:%s')



order by a.alarm_time desc

SELECT t1.device_code, count(*) AS count FROM `vm_checkpoint_warning_order_t` t1 WHERE t1.delete_flag = '0' and t1.device_code in
#{item}
and #{alarmTimeEnd} >= date_format(t1.alarm_time,'%Y-%m-%d')
and date_format(t1.alarm_time,'%Y-%m-%d') >= #{alarmTimeStart}
${dataScope} GROUP BY t1.device_code

SELECT DISTINCT t1.device_code, (case when length(IFNULL(tdr.device_name, '')) = 0 then t2.device_name else tdr.device_name end ) as device_name, t2.longitude, t2.latitude, 0 as count FROM vm_checkpoint_device_info_t t1 LEFT JOIN vm_order_devices t ON t1.device_code = t.device_code AND t.delete_flag = '0' AND t1.tenant_id = t.tenant_id AND t1.industry_code = t.industry_code LEFT JOIN vm_order_package vop ON t.order_code = vop.order_code AND t.delete_flag = '0' LEFT JOIN vm_order_customer voc ON t.order_code = voc.order_code LEFT JOIN vm_tenant_device_channel_rel_t tdr on tdr.device_code = t1.device_code AND tdr.tenant_id = t1.tenant_id AND tdr.industry_code = t1.industry_code, vm_device_info_t t2 WHERE t1.device_code = t2.device_code AND t1.delete_flag = 0 AND t2.delete_flag = '0' AND voc.delete_flag = '0' AND voc.ord_status IN ( 0, 1, 2 )
and t2.province_id = #{provinceCode}
and t2.city_id = #{cityCode}
and t2.county_id = #{countyCode}
and t2.town_code = #{townCode}
${dataScope}

        SELECT
        t1.device_code as deviceCode,
        t1.vehicle_number,
        DATE_FORMAT(t1.alarm_time,'%Y-%m-%d') time,
		count(*) count
        FROM
            vm_checkpoint_warning_order_t t1

            AND t1.delete_flag = 0

                and t1.vehicle_number in

                    #{item}



                and t1.device_code in

                    #{item}



                AND  DATE_FORMAT( t1.alarm_time, '%Y-%m-%d' ) <= #{queryEndTime}


                and  DATE_FORMAT( t1.alarm_time, '%Y-%m-%d' ) >= #{queryStartTime}


                and t1.tenant_id = #{tenantId}


                and t1.industry_code = #{industryCode}


        GROUP BY DATE_FORMAT(t1.alarm_time,'%Y-%m-%d'),t1.vehicle_number,t1.device_code
